\label{thm1.1}  Let $(M,g)$ be an $n$-dimensional connected compact Riemannian manifold.
Then, if all the sectional curvatures are {\em nonpositive}, for $\lambda\gg1$ we have the uniform bounds
\begin{equation}\label{1.7}
\bigl\| \chi_{[\lambda, \lambda+(\log\lambda)^{-1}]} f\bigr\|_{L^q(M)}\le C\bigl(\lambda (\log\lambda)^{-1}\bigr)^{\mu(q)} \|f\|_{L^2(M)}, \, \, \,
2<q\le q_c,
\end{equation}
with $q_c$ and $\mu(q)$ as in \eqref{1.1} and \eqref{1.4}, respectively.  Moreover, if all the sectional
curvatures of $M$ are {\em negative}, for $\lambda\gg 1$ we have the uniform bounds
\begin{equation}\label{1.8}
\bigl\| \chi_{[\lambda, \lambda+(\log\lambda)^{-1}]} f\bigr\|_{L^q(M)}\le C_q \, \lambda^{\mu(q)} (\log\lambda)^{-1/2} \|f\|_{L^2(M)}, \, \, \,
2<q\le q_c,
\end{equation}
with the constant $C_q$ in \eqref{1.8} depending on $q$.

\label{thm1.2}  Assume that $(M,g)$ is a connected compact manifold of constant
sectional curvature $K$ and fix {\em any} exponent
$q\in (2,q_c]$.
Then, if $\mu(q)$ is as in \eqref{1.4},
\begin{multline}\label{shape}

 \sup \bigl\{ \|\Phi_\lambda\|_{L^q(M)}: \, \Phi_\lambda \in V_{[\lambda,\lambda+(\log)^{-1}]}, \, 
\|\Phi_\lambda\|_{L^2(M)}=1 \bigr\} 
\\
=\begin{cases}
\Theta(\lambda^{\mu(q)}(\log\lambda)^{-1/2}) \, \, \iff \, \, K<0
\\
\Theta(\lambda^{\mu(q)}(\log\lambda)^{-\mu(q)}) \, \, \iff \, \, K=0
\\
\Theta(\lambda^{\mu(q)}) \, \, \iff \, \, K>0.
\end{cases}
\end{multline}
Also, if $(\log\lambda)^{-1}\le \delta(\lambda)\searrow 0$ as $\lambda\to \infty$ and $\lambda\to \lambda \, \delta(\lambda)$ is non-decreasing for $\lambda\ge2$,
\begin{multline}\label{shape2}

 \sup \bigl\{ \|\Phi_\lambda\|_{L^q(M)}: \, \Phi_\lambda \in V_{[\lambda,\lambda+\delta(\lambda)]}, \, 
\|\Phi_\lambda\|_{L^2(M)}=1 \bigr\} 
\\
=\begin{cases}
\Theta(\lambda^{\mu(q)}(\delta(\lambda))^{1/2}) \, \, \iff \, \, K<0
\\
\Theta(\lambda^{\mu(q)}(\delta(\lambda))^{\mu(q)}) \, \, \iff \, \, K=0
\\
\Theta(\lambda^{\mu(q)}) \, \, \iff \, \, K>0.
\end{cases}
\end{multline}

\label{smallprop}
Suppose that all of the sectional curvatures of $(M,g)$ are nonpositive.  Then for $\lambda\gg1$ and $T$ as in \eqref{2.1} we have
\begin{equation}\label{2.23}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)}\le C (\lambda T^{-1})^{1/q_c},
\end{equation}
and if all the sectional curvatures are negative
\begin{equation}\label{2.24}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)}\le C \lambda^{1/q_c} \,  T^{-1/2}.
\end{equation}

\label{alemma}  Let $\theta_0=\lambda^{-1/8}$.  Then
\begin{align}\label{2.33}
\|A^{\theta_0}_\nu h\|_{\ell_\nu^q L^q(M)} &\lesssim \|h\|_{L^q(M)}, \quad 2\le q\le \infty,
\\
\bigl\|\sum_{\nu'}(A^{\theta_0}_{\nu'})^* H(\nu',\, \cdot\, )\bigr\|_{L^p(M)} &\lesssim \|H\|_{\ell^p_{\nu'}L^p(M)}, \quad 1\le p\le 2.
\label{2.34}
\end{align}
Also, if $\delta>0$ in \eqref{2.2} is small enough and $\mu(q)$ is as in \eqref{1.4}
\begin{equation}\label{commute}
\|B\sigma_\lambda A^{\theta_0}_\nu - BA^{\theta_0}_\nu \sigma_\lambda \|_{2\to q}=O(\lambda^{\mu(q)-\frac14}), \quad q\in (2,q_c].
\end{equation}

\label{locprop}
If $n\ge2$ and $\theta_0=\lambda^{-1/8}$, $\lambda\gg1$ and if \eqref{2.15} is valid
\begin{equation}\label{2.44}
\|\tilde \sigma_\lambda h\|_{L^{q_c}(A_-)}\lesssim \Bigl(\, \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu h\|_{L^{q_c}(M)}^{q_c}\, 
\Bigr)^{1/q_c} + \lambda^{\frac1{q_c}-}, \quad \text{if } \,  h=\rho_\lambda f,
\end{equation}
assuming that the conic support of $B(x,\xi)$ in \eqref{2.8} is small and that $\delta$ and $\delta_0$ in \eqref{2.2} are also small.
Also, if $2<q\le \tfrac{2(n+2)}n$,
\begin{equation}\label{2.45}
\|\tilde \sigma_\lambda h\|_{L^{q}(M)}\lesssim \Bigl(\, \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu h\|_{L^{q}(M)}^{q}\, 
\Bigr)^{1/q} + \lambda^{\mu(q)-}\|h\|_{L^2(M)}.
\end{equation}

\label{kerprop} Let $\theta_0=\lambda^{-1/8}$ and
 assume that
for $T=c_0\log\lambda$ as in \eqref{2.1} 
we have the following bounds for
the microlocalized kernels
\begin{equation}\label{ker}
|\bigl(A_\nu^{\theta_0} G_{\lambda,T,N}(A_{\nu'}^{\theta_0})^*\bigr)(x,y)|
\le CT^{-1}\lambda^{\frac{n-1}2}N^{1-\alpha}, \, \, N=2^j, \, \, j\in {\mathbb N}.
\end{equation}
We then have                     
\begin{equation}\label{est}
\|A_\nu^{\theta_0} \rho_\lambda f\|_{\ell^{q_c}_\nu L^{q_c}(M)}
\le C \lambda^{\frac1{q_c}} \|f\|_{L^2(M)} \cdot
\begin{cases}
T^{-\frac\alpha{n+1}}, \quad \text{if } \, 
\alpha <\tfrac{n+1}2
\\
T^{-\frac12}, \quad \text{if } \, \alpha>\frac{n+1}2.
\end{cases}
\end{equation}
Also, if $q\in (2,q_c)$ we have
\begin{equation}\label{est2}
\|A_\nu^{\theta_0} \rho_\lambda f\|_{\ell_\nu^q L^q(M)}\le C\lambda^{\mu(q)} T^{-1/2} \|f\|_{L^2(M)}, \quad
\text{if } \, \alpha>\tfrac{q}{q-2}.
\end{equation}

We first note that by \eqref{2.11} and \eqref{2.44} we have
\begin{equation}\label{2.55}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)} \lesssim 
\Bigl(\, \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{L^{q_c}(M)}^{q_c} \, \Bigr)^{1/q_c}
+\lambda^{\frac1{q_c}-}\|f\|_2,
\end{equation}
since $\|\rho_\lambda\|_{2\to2}=O(1)$.  Consequently, to prove the bounds in it suffices to show that the first term in
the right is dominated by the right side of \eqref{2.23} when all of the sectional curvatures of $M$ are nonpositive
and by the right side of \eqref{2.24} if they all are negative.  We recall that we are assuming as in \eqref{2.15} that
$f$ is $L^2$-normalized.

We first note that, since $\mu(q_c)=1/q_c$,
 by using \eqref{2.10}, \eqref{commute} and \eqref{2.33}, we obtain
\begin{multline}\label{2}
\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|^{q_c}_{L^{q_c}(M)}
=\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^2
\cdot \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^{q_c-2}
\\
\le
\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^2
\cdot \| BA^{\theta_0}_\nu\sigma_\lambda  \rho_\lambda f\|_{q_c}^{q_c-2}
\\
\qquad \qquad \qquad\qquad \qquad+ \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^2
\cdot \| (BA^{\theta_0}_\nu\sigma_\lambda-B\sigma_\lambda A^{\theta_0}_\nu) \rho_\lambda f\|_{q_c}^{q_c-2}
\\
\lesssim \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^2
\cdot \| B A^{\theta_0}_\nu\sigma_\lambda  \rho_\lambda f\|_{q_c}^{q_c-2}
+\sum_\nu \lambda^{\frac2{q_c}}\|A^{\theta}_\nu\rho_\lambda f\|_2^2
\cdot \lambda^{(\frac1{q_c}-\frac14)(q_c-2)}\|\rho_\lambda f\|_2^{q_c-2}
\\
\lesssim 
\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^2
\cdot \| B A^{\theta_0}_\nu\sigma_\lambda  \rho_\lambda f\|_{q_c}^{q_c-2}
+\lambda^{1-\frac14(q_c-2)}
\\
\le C
\bigl(\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|_{q_c}^{q_c}\bigr)^{\frac2{q_c}}
\bigl(\sum_\nu \|B A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c}\bigr)^{\frac{q_c-2}{q_c}} +C\lambda^{1-\frac14(q_c-2)},
\end{multline}
using also H\"older's inequality in the last line.

By Young's inequality, we can bound the second to last
term as follows
\begin{multline*}C\bigl(\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|_{q_c}^{q_c}\bigr)^{\frac2{q_c}}
\bigl(\sum_\nu \|B A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c}\bigr)^{\frac{q_c-2}{q_c}}
\\
=C \delta \bigl(\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|_{q_c}^{q_c}\bigr)^{\frac2{q_c}}
\cdot \delta^{-1}
\bigl(\sum_\nu \|B A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c}\bigr)^{\frac{q_c-2}{q_c}}
\\
\le C \Bigl[ \tfrac2{q_c}\delta^{\frac{q_c}2} \sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|_{q_c}^{q_c}
+ 
\tfrac{q_c-2}{q_c}\delta^{-\frac{q_c}{q_c-2}}
\sum_\nu \| BA^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c} \Bigr].
\end{multline*}
If $\delta>0$ is small enough so that $C\tfrac2{q_c}\delta^{\frac{q_c}2}$
 is smaller than $1/2$, we can absorb the contribution
of the first term in the right side of the preceding inequality into the left side
of \eqref{2} and conclude that
\begin{align}\label{3}
\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu \rho_\lambda f
\|^{q_c}_{L^{q_c}(M)}
&\lesssim \sum_\nu \|B A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c}+\lambda^{1-\frac14(q_c-2)}.
\\
&\lesssim  \sum_\nu \| A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}
^{q_c}+\lambda^{1-\frac14(q_c-2)}, \notag
\end{align}
using \eqref{2.9} in the last line.  Next, if we use \eqref{2.12} along with the  $L^{q_c}$ almost orthogonality bounds in \eqref{2.33} we can control
the nontrivial term on the right as follows
\begin{equation}\label{2.58}
 \sum_\nu \| A^{\theta_0}_\nu \sigma_\lambda \rho_\lambda f\|_{q_c}^{q_c} 
 \lesssim  \sum_\nu \| A^{\theta_0}_\nu \rho_\lambda f\|_{q_c}^{q_c} + T^{-q_c}\lambda.
\end{equation} 

If we combine \eqref{2.55}--\eqref{2.58}, we conclude that
\begin{equation}\label{2.59}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)}\lesssim \|A^{\theta_0}_\nu \rho_\lambda f\|_{\ell_\nu^{q_c}L^{q_c}(M)}+O(\lambda^{\frac1{q_c}-}+T^{-1}\lambda^{\frac1{q_c}}).
\end{equation}
If the sectional curvatures of $M$ are all nonpositive we conclude from Lemma~\ref{globalker} that \eqref{ker} is valid for
$\alpha=\tfrac{n-1}2$, and so, by \eqref{est} in Proposition~\ref{kerprop} we obtain in this case
\begin{multline}\label{2.60}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)}
\lesssim \|A^{\theta_0}_\nu \rho_\lambda f\|_{\ell_\nu^{q_c}L^{q_c}(M)} +O(\lambda^{\frac1{q_c}-}+T^{-1}\lambda^{\frac1{q_c}})
\\
\lesssim T^{-\frac1{n+1}\cdot
\frac{n-1}2} \lambda^{\frac1{q_c}}
=(T^{-1}\lambda)^{\frac1{q_c}} \approx (\lambda(\log\lambda)^{-1})^{\mu(q_c)},
\end{multline}
which along with the earlier bound \eqref{2.18} yields \eqref{1.7} for $q=q_c=\tfrac{2(n+1)}{n-1}$.

If all of the sectional curvatures of $M$ are negative, then Lemma~\ref{globalker} says that \eqref{ker} is valid for any $\alpha\in {\mathbb N}$ and so we can use the more favorable case of \eqref{est} involving $T^{-1/2}$.  As a result, if we repeat the arguments leading to \eqref{2.60}
we conclude that if all the sectional curvatures of $M$ are negative we have
\begin{equation}\label{2.61}
\|\tilde \rho_\lambda f\|_{L^{q_c}(A_-)}\lesssim \lambda^{\mu(q_c)} (\log\lambda)^{-1/2},
\end{equation}
which along with \eqref{2.18} yields \eqref{1.8} for the critical index $q=q_c$.

If $Uf(x,\nu)=A_\nu \rho_\lambda f(x)$, then \eqref{est}
is equivalent to
\begin{equation}\label{8}
\|UU^*\|_{\ell^{q_c'}_{\nu'}L^{q_c'}\to \ell^{q_c}_\nu L^{q_c}}
\lesssim 
\begin{cases}
T^{-\frac{2\alpha}{n+1}} \lambda^{\frac2{q_c}}, \, \, \text{if } \, \alpha<\tfrac{n+1}2,
\\
T^{-1} \lambda^{\frac2{q_c}}, \, \, \text{if } \, \alpha>\tfrac{n+1}2,
\end{cases}
\end{equation}
with
\begin{align}\label{9}
\bigl(UU^*F\bigr)(x,\nu)&=\sum_{\nu'}
\Bigl(\bigl(A^{\theta_0}_\nu \circ \rho^2(T(\lambda-P))\circ (A^{\theta_0}_{\nu'})^*\bigr)F(\, \cdot \, ,\nu')\Bigr)(x)
\\
&= \sum_{\nu'}\Bigl(\bigl(A^{\theta_0}_\nu \circ L_{\lambda,T}\circ (A^{\theta_0}_{\nu'})^* \bigr)F(\, \cdot \, ,\nu')\Bigr)(x) \notag
\\ &\qquad 
+\sum_{2\le N=2^j\le T} 
\Bigl[\sum_{\nu'}\Bigl(\bigl(A^{\theta_0}_\nu \circ G_{\lambda,T,N}\circ (A^{\theta_0}_{\nu'})^* \bigr)F(\, \cdot \, ,\nu')\Bigr)(x)
\Bigr].
\notag
\end{align}

If we use \eqref{2.33} and \eqref{2.34} along with \eqref{loc} 
 we obtain
\begin{align}\label{localpart}
\Bigl\| \sum_{\nu'}\Bigl(\bigl(A^{\theta_0}_\nu \circ &L_{\lambda,T}\circ (A^{\theta_0}_{\nu'})^* \bigr)F(\, \cdot \, ,\nu')\Bigr)(\, \cdot \,)
\Bigr\|_{\ell^{q_c}_\nu L^{q_c}}
\\
&\le 
\Bigl\| \sum_{\nu'} \bigl(L_{\lambda,T}\circ (A^{\theta_0}_{\nu'})^*\bigr)F(\, \cdot \, ,\nu')\Bigr)(\, \cdot \,)
\Bigr\|_{L^{q_c}} \notag
\\
&\le T^{-1}\lambda^{\frac2{q_c}}
\Bigl\| \sum_{\nu'} (A^{\theta_0}_{\nu'})^* F(\, \cdot \, ,
\nu')\Bigr\|_{L^{q_c'}} \notag
\\
& \le T^{-1}\lambda^{\frac2{q_c}} \|F\|_{\ell^{q_c'}_{\nu'}L^{q_c'}}
\notag
\end{align}
which is better than the bounds in \eqref{8} if $\alpha<\tfrac{n+1}2$ and agrees with them
for $\alpha>\tfrac{n+1}2$.

To finish the proof of \eqref{8}, we also need
to estimate the $N$-summands in \eqref{9},
\begin{equation}\label{W}
W_N F = \sum_{\nu'}\Bigl(\bigl(A^{\theta_0}_\nu \circ G_{\lambda,T,N}\circ (A^{\theta_0}_{\nu'})^* \bigr)F(\, \cdot \, ,\nu')\Bigr)(x),
\quad N=2^j, \, j\in {\mathbb N}.
\end{equation}

By \eqref{global} we clearly have
$$\|G_{\lambda,T,N}\|_{L^2(M)\to L^2(M)}=O(T^{-1}N).$$
So, if we use \eqref{2.33} and \eqref{2.34}  for $q=2$  the preceding argument yield
for $2\le 2^j=N$
\begin{equation}\label{w2}
\|W_N\|_{\ell^2_{\nu'}L^2\to \ell^2_\nu L^2}=O(T^{-1}N).
\end{equation}
We
also obtain from \eqref{ker}
\begin{equation}\label{winfty}
\|W_N\|_{\ell^1_{\nu'}L^1\to \ell^\infty_\nu L^\infty}=O(T^{-1}\lambda^{\frac{n-1}2}N^{1-\alpha}).
\end{equation}

If we interpolate between these two estimates
we obtain
\begin{equation}\label{interpolate}
\|W_N\|_{\ell^{q_c'}_{\nu'} L^{q_c'}\to \ell^{q_c}_\nu L^{q_c}}
=O(T^{-1}\lambda^{\frac2{q_c}}N^{1-\frac{2\alpha}{n+1}}).
\end{equation}
Whence,
\begin{equation}\label{globalpart}
\sum_{2\le 2^j=N\le T}
\|W_N\|_{\ell^{q_c'}_{\nu'} L^{q_c'}\to \ell^{q_c}_\nu L^{q_c}}
\lesssim \begin{cases}
T^{-\frac{2\alpha}{n+1}} \lambda^{\frac2{q_c}}, \, \, \text{if } \, \alpha<\tfrac{n+1}2,
\\
T^{-1} \lambda^{\frac2{q_c}}, \, \, \text{if } \, \alpha>\tfrac{n+1}2.
\end{cases}
\end{equation}

If we combine \eqref{9}, \eqref{localpart} and
\eqref{globalpart}, we obtain \eqref{8}.
The same argument yields \eqref{est2} which
finishes the proof of Proposition~\ref{kerprop}.

\label{lemma4.2}  Let for $T=\delta^{-1}=\log\lambda$ as above
\begin{equation}\label{4.12}
K_\lambda(z)=\int e^{iz\cdot \xi}a_{\lambda,\delta}(\xi) \, \eta(T(\lambda-|\xi|)) \, d\xi.
\end{equation}
Then if $c_0>0$  in \eqref{4.6} is fixed small enough and $c>0$ is fixed we have
for $\lambda\gg 1$ the uniform bounds
\begin{equation}\label{4.13}
|K_\lambda(z)|+|\nabla K_\lambda(z)|\le C_N \lambda^{-N} \, \, \forall \, N,
\quad \text{if } \, \, |z'|>c.
\end{equation}
Also, assuming that $T\ge1$, 
\begin{equation}\label{4.14}
|K_\lambda(z)|\le C_N\bigl( \, |z|+\lambda\, \bigr)^{-N} \, \, \forall \, N, \, \,
\, \text{if } \, |z|\ge 2T.
\end{equation}

To complete the proof of our results for flat compact manifolds, we must prove
\eqref{4.5}.  Unlike the proof of \eqref{4.4}, to prove this lower bound, we shall need to assume \eqref{4.11} to ensure
that there is no cancellation in the nontrivial terms in the sum \eqref{4.10} defining $\psi_{\lambda_k}$.

To prove this lower bound, consider our unit speed geodesic $\tilde \gamma(t)$ in $D$, and the
associated $\lambda^{-1/2}\delta^{-1/2}$--tubes about the
segment $\tilde \gamma(t)$, $|t|\le \overline{c}$, where $\overline{c} \in (0,1)$ will be fixed small enough in the ensuing calculation.  In particular,
it will be small enough so that there are no crossing points along $\gamma_0(t)\in M$ for $|t|\le \overline{c}$.

As before, $\delta=(\log\lambda)^{-1}$, and so with $\lambda=\lambda_k$ as above, we let
\begin{equation}\label{4.16}
{\mathcal T}_k =\bigl\{y\in D: \, \text{dist}((\tilde \gamma(t),y)\le \lambda_k^{-1/2}(\log\lambda_k)^{1/2}, \, \, |t|\le \overline{c}\bigr\}
\end{equation}
denote a $\lambda_k^{-1/2}\delta^{-1/2}_k$-tube about this segment.  Note that
$|{\mathcal T}_k|\approx \lambda^{-\frac{n-1}2}_k(\log\lambda_k)^{\frac{n-1}2}$, and so, by H\"older's inequality, if $q\in (2,q_c]$
\begin{align*}
\| \psi_{\lambda_k}\|_{L^2({\mathcal T}_k)}&\lesssim \bigl(\lambda_k^{-\frac{n-1}2}(\log\lambda_k)^{\frac{n-1}2}\bigr)^{(\frac12-\frac1{q})} \,
\|\psi_{\lambda_k}\|_{L^{q}(D)}
\\
&=\lambda^{-\mu(q)}_k \delta_k^{-\mu(q)}\|\psi_{\lambda_k}\|_{L^{q}(D)},  \, \, \, \delta_k=(\log\lambda_k)^{-1},
\end{align*}
since $\mu(q)=\tfrac{n-1}2(\tfrac12-\tfrac1q)$ for $q\in (2,q_c]$.
As a result, we would have the lower bound \eqref{4.5} and be done if we could show that for fixed $c_0>0$ as in \eqref{4.6} we have
\begin{equation}\label{4.17}
\|\psi_{\lambda_k}\|_{L^2({\mathcal T}_k)}\ge c_1
\end{equation}
for some uniform $c_1>0$ when $\lambda_k\gg 1$.

To prove \eqref{4.17}, by calculus, it suffices to show that we have the uniform bounds
\begin{equation}\label{4.18}
|\psi_k(\tilde \gamma(t))|\ge c_1 \lambda_k^{\frac{n-1}4}\delta_k^{\frac{n-1}4},  \, \, \text{some }
c_1>0, \, \, \text{if } \, \, |t|\le \overline{c},
\end{equation}
if $\overline{c}>0$ as above is small enough, and also the upper bound
\begin{equation}\label{4.19}
|\nabla_{y'}\psi_{\lambda_k}(y)|\le C
\lambda_k^{\frac{n-1}4}\delta_k^{\frac{n-1}4} \cdot (\lambda_k\delta_k)^{1/2}, \, \, \,
\delta_k=(\log\lambda_k)^{-1}, \, \, y\in {\mathcal T}_k.
\end{equation}
We can use \eqref{4.19} along with \eqref{4.17} to obtain \eqref{4.17} since
$\tilde \gamma(t)=(t,0,\dots,0)$.

As we shall see, \eqref{4.19} follows from the proof of \eqref{4.15} and does not require that $\lambda$
be as in \eqref{4.11}.  So, let us focus first on \eqref{4.18}, which is the more difficult to prove.

To prove \eqref{4.18} we shall need to use the properties of the stabilizer group $G_{\gamma_0}$ of 
our periodic geodesic of length $\ell_0$ that we described before.  It is a cyclic subgroup of 
$\Gamma$ generated by $\alpha_{\gamma_0}\in \Gamma$ as in \eqref{4.2} and \eqref{4.3}.  Since $\gamma_0$ loops
back smoothly through $0$ with no other crossings there, as we mentioned before, 
$\alpha(0)\in \tilde \gamma$, the lift of $\gamma_0$, if and only $\alpha\inG_{\gamma_0}$.

From this we deduce that if $\alpha\notinG_{\gamma_0}$ we must have that
$\text{dist}(\alpha(0),\tilde \gamma)\ge c$ for some uniform constant $c>0$.    This implies that
if $\overline{c}$ in \eqref{4.16} is fixed small enough then for large enough $\lambda_k$ we have
for $c_1=c/2$
\begin{equation}\label{4.20}
\text{dist}(\alpha({\mathcal T}_k), \tilde \gamma)\ge c_1, \quad \text{if } \, \alpha\notinG_{\gamma_0}.
\end{equation}
Thus, by Lemma~\ref{lemma4.2}, if $\psi_{\lambda_k,\alpha}$ denotes the $\alpha$-summand
in the definition \eqref{4.10} of $\psi_{\lambda_k}$, i.e.,
\begin{equation}\label{4.21}
\psi_{\lambda_k,\alpha}(y)=(\lambda_k\delta_k)^{-\frac{n-1}4}
\int_{{\mathbb R}^n} e^{i\alpha(y)\cdot\xi} a_{\lambda_k, \delta_k}(\xi) \eta(T_k(\lambda_k-|\xi|)) \, d\xi,
\, \,  T_k=\delta_k^{-1}=\log\lambda_k,
\end{equation}
we must have
\begin{multline}\label{4.22}
|\psi_{\lambda_k,\alpha}(y)|+|\nabla \psi_{\lambda_k,\alpha}(y)|
\le C_N \, \bigl(\alpha(y)+\lambda_k\bigr)^{-N},
\\
\text{if } \, \, y\in {\mathcal T}_k \, \, \text{and } \, \, \alpha\notinG_{\gamma_0} \, \, \,
\text{or } \, \, \, \text{dist}(\alpha(y),0)\ge 2T_k.
\end{multline}

Thus, if $\alpha_{\gamma_0}$ as in \eqref{4.3} is the generator of $G_{\gamma_0}$, we have for $T_k$ and $\delta_k$ as above
\begin{multline}\label{4.23}
\psi_{\lambda_k}(y)=
\sum_{\{j\in {\mathbb Z}: \, \text{dist}(\alpha_{\gamma_0}^j(D),0)\le 2T_k\}} \lambda_k^{-\frac{n-1}4}\delta_k^{-\frac{n-1}4}
\int e^{i\alpha_{\gamma_0}^j(y)\cdot \xi} a_{\lambda_k, \delta_k}(\xi) \eta(T_k(\lambda_k-|\xi|)) \, d\xi
\\
+O(\lambda_k^{-N}) \quad \text{if } \, \, y\in {\mathcal T}_k.
\end{multline}
If $y=\tilde \gamma(t)=(t,0,\dots,0)$, $|t|\le \overline{c}$, then by \eqref{4.2} and \eqref{4.3}
$$\alpha_{\gamma_0}^j(\tilde \gamma(t))\cdot \xi = (t+j\ell_0) \xi_1, \quad |t|\le \overline{c},$$
since $\alpha_{\gamma_0}^j(0)=(j\ell_0,0,\dots,0)$.  Thus since $\beta(|\xi|/\lambda_k)=1$ for $|\xi|\in (\lambda_k/2,2\lambda_k)$ and $\eta\in {\mathcal S}$,
by \eqref{4.8},
\begin{multline}\label{4.24}
\psi_{\lambda_k}((\tilde \gamma(t))=
\\
\sum_{\{j\in {\mathbb Z}: \, |j\ell_0|\le 2T_k\}}
(\lambda_k\delta_k)^{-\frac{n-1}4}\int
e^{i (t+j\ell_0)\xi_1} a(\lambda_k^{1/2}\delta_k^{-1/2}|e_1-|\xi/|\xi| \, |) \, \eta(T_k(\lambda_k-|\xi|)) \, d\xi
\\
+O(\lambda_k^{-N}), 
\, \, |t|\le \overline{c}.
\end{multline}

Next, let us polar coordinates $\xi=r\omega$, $r>0$, $\omega\in S^{n-1}$ so that $\xi/|\xi|=\omega$.
We then write each summand as above as
\begin{align*}
&(\lambda_k\delta_k)^{-\frac{n-1}4}
\int_{S^{n-1}} \int_0^\infty e^{i(t+j\ell_0)r\omega_1} a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, \eta(T_k(\lambda_k-r)) \,
r^{n-1}dr d\omega
\\
&= (\lambda_k\delta_k)^{-\frac{n-1}4}
\int_{S^{n-1}}
\Bigl(\int_{-\lambda_k}^{\infty} e^{i(t+j\ell_0)(\lambda_k+r)\omega_1} \eta(-T_k r) \,
(\lambda_k+r)^{n-1}dr \Bigr) a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, d\omega
\\
&= (\lambda_k\delta_k)^{-\frac{n-1}4}
\int_{S^{n-1}}
\Bigl(\lambda_k^{n-1}\int_{-\infty}^{\infty}  e^{i(t+j\ell_0)(\lambda_k-r)\omega_1} \eta(T_k r) \,
dr \Bigr) a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, d\omega
\\
&\qquad\qquad \qquad +O(\lambda_k^{n-2}\lambda_k^{-\frac{3(n-1)}4}\delta_k^{\frac{n-1}4}),
\end{align*}
since $r^m\eta(r)\in {\mathcal S}({\mathbb R})$, $0\le m\le n-2$, and, by \eqref{4.7},
\begin{equation}\label{4.25}
\int_{S^{n-1}}a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, d\omega
\approx \lambda_k^{-\frac{n-1}2}\delta_k^{\frac{n-1}2}.
\end{equation}
Since there are $O(T_k)=O(\delta_k^{-1})$ terms in the sum in \eqref{4.24}, we conclude that for $|t|\le \overline{c}$
\begin{multline}\label{4.26}
\psi_{\lambda_k}(\tilde \gamma(t))
=
\\
\lambda_k^{n-1}(\lambda_k \delta_k)^{-\frac{n-1}4}
\sum_{ |j\ell_0|\le 2T_k} \int_{S^{n-1}} e^{i(t+\ell_0j)\lambda_k \omega_1}
 T_k^{-1} \Hat \eta(T_k^{-1}(t+j\ell_0)w_1) \, a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, d\omega
 \\
 +O\bigl( (\lambda_k/\delta_k)^{-1} \lambda_k^{\frac{n-1}4}\delta_k^{\frac{n-1}4}\bigr).
 \end{multline}
 If the integrand here is nonzero, then by \eqref{4.6}, \eqref{4.7} and \eqref{4.8}, we must have that
 $\omega_1-1=O(\lambda_k^{-1}\delta_k)$ and $t+j\ell_0=O(c_0T_k)=O(c_0\delta_k^{-1})$, and so
 \begin{align}\label{4.27}
 e^{i(t+\ell_0j)\lambda_k \omega_1}&=e^{it\lambda_k} e^{i\ell_0j\lambda_k}+O(c_0)
 \\
 &=e^{it\lambda_k}e^{2\pi ijk}+O(c_0) \notag
 \\
 &=e^{it\lambda_k}+O(c_0), \, \, \, \text{if } \, |t|\le \overline{c}<1,
 \notag
 \end{align}
 due to our choice in \eqref{4.11} of the frequency of our log-quasimode.
 By \eqref{4.6} each $\Hat \eta$ factor in the sum in \eqref{4.26} is nonnegative.  So, since
 for $|t|\le \overline{c}$, with $\overline{c}$ small enough,
 $|(t+j\ell_0)\omega_1| \approx |j|$ if $j\ne0$ and $a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|)\ne0$,
 we see by \eqref{4.6} and \eqref{4.25},
 \begin{equation}\label{4.28}
 \sum_{ |j\ell_0|\le 2T_k} \int_{S^{n-1}}  
 T_k^{-1} \Hat \eta(T_k^{-1}(t+j\ell_0)w_1) \, a(\lambda_k^{1/2}\delta_k^{-1/2}|\omega-e_1|) \, d\omega
 \approx \lambda_k^{-\frac{n-1}2}\delta_k^{\frac{n-1}2}.
 \end{equation}

 We obtain \eqref{4.18} by combining \eqref{4.26}, \eqref{4.27} and \eqref{4.28} if 
 $c_0$ and $\overline{c}$ are small enough and $\lambda_k\gg 1$.

 To prove the remaining inequality \eqref{4.19}, we use Lemma~\ref{lemma4.2} and the above arguments
 to see that
 \begin{equation}\label{4.29}
 \nabla_{y'}\psi_{\lambda_k}(y)=\sum_{\{j\in {\mathbb Z}: \, |j\ell_0|\le 2T_k\}} \nabla_{y'}
 \psi_{\lambda_k,\alpha_{\gamma_0}^j}(y)+O(\lambda_k^{-N}), \quad \text{if } \, y\in {\mathcal T}_k,
 \end{equation}
 where $\psi_{\lambda_k,\alpha}$ is as in \eqref{4.21}.  Recall that $\alpha_{\gamma_0}$ is as in \eqref{4.3}.
 If $\overline{m}\in O_{n-1}$ is as in \eqref{4.2}, then
 $$ \psi_{\lambda_k,\alpha_{\gamma_0}^j}(y)=\lambda_k^{-\frac{n-1}4}\delta_k^{-\frac{n-1}4}
 \int
 e^{i(y_1+j\ell_0)\xi_1} e^{iy'\cdot (\overline{m})^j \xi'}
 a_{\lambda_k, \delta_k}(\xi) \eta(T_k((\lambda-|\xi|)) \, d\xi.$$
 Since $|(\overline{m})^j\xi'|=|\xi'|=O(\lambda_k^{1/2}\delta_k^{1/2})$ on the support of the integral,
 we can argue as above to deduce
 that
 $$\nabla_{y'}\psi_{\lambda_k,\alpha_{\gamma_0}^j}(y)=O\bigl(T_k^{-1}\lambda_k^{\frac{n-1}4}\delta_k^{\frac{n-1}4} \, (\lambda_k\delta_k)^{1/2}\bigr),
 \quad \text{if } \, y\in {\mathcal T}_k,$$
 which yields \eqref{4.19} after recalling \eqref{4.29}.  \qed

\label{diag1}  If $\Upsilon^{\text{diag}}(h)$
is as in \eqref{diag} and $n\ge3$, then we have the
uniform bounds
\begin{equation}\label{star}
\|\Upsilon^{\text{diag}}(h)\|_{L^{q_c/2}}
\lesssim \bigl(\sum_\nu \|\tilde \sigma_\lambda
A^{\theta_0}_\nu h\|_{L^{q_c}}^{q_c})^{2/q_c}
+O(\lambda^{\frac2{q_c}-}\|h\|^2_2).
\end{equation}
And for all $n\ge 2$, if $q\in (2, \frac{2(n+2)}{n}]$ and $\mu(q)$ is as in \eqref{1.4},  we have 
\begin{equation}\label{star1}
\|\Upsilon^{\text{diag}}(h)\|_{L^{q/2}}
\lesssim \bigl(\sum_\nu \|\tilde \sigma_\lambda
A^{\theta_0}_\nu h\|_{L^{q}}^{q})^{2/q}
+O(\lambda^{2\mu(q)-}\|h\|^2_2).
\end{equation}
Also if $n=2$ and ${\overline\Upsilon^{\text{diag}}}(h)$ is  as in \eqref{organize}, we have 
\begin{equation}\label{star2}
\|{\overline\Upsilon^{\text{diag}}}(h)\|_{L^{3/2}}
\lesssim \bigl(\sum_\nu \|\tilde \sigma_\lambda
A^{\theta_0}_\nu h\|_{L^{6}}^{6})^{2/3}
+O(\lambda^{\frac2{3}-}\|h\|^4_2).
\end{equation}

\label{leelemma}  Let $n\ge2$.
 If $\Upsilon^{\text{far}}(h)$ is as in \eqref{5.4}, and, as above $\theta_0=\lambda^{-1/8}$ then for
all $\varepsilon>0$ we have
\begin{equation}\label{5.7}
\int_M |\Upsilon^{\text{far}}(h)|^{q/2}\, dx \le C_\varepsilon \lambda^{1+\varepsilon}
\bigl(\lambda^{7/8}\bigr)^{\frac{n-1}2 (q-q_c)} \, 
\|h\|^q_{L^2(M)}, \quad \,q= \tfrac{2(n+2)}n,
\end{equation}
assuming, as in Proposition~\ref{locprop}, that the conic support of $B(x,\xi)$ in \eqref{2.8} as well as $\delta$ and $\delta_0$
in \eqref{2.2}
are sufficiently small.
Similarly, for all $n\ge 2$, we have
\begin{equation}\label{5.7q}
\int_M |\Upsilon^{\text{far}}(h)|^{q/2}\, dx \le C \lambda^{\mu(q)\cdot q-}
 \, 
\|h\|^q_{L^2(M)}, \quad \,2<q< \tfrac{2(n+2)}n.
\end{equation}
Also if $n=2$ and ${\overline\Upsilon^{\text{far}}}(h)$ is as in \eqref{organize}, we have
\begin{equation}\label{5.7'}
\int_M |{\overline\Upsilon^{\text{far}}}(h)|\, dx \le C_\varepsilon \lambda^{1+\varepsilon}
\lambda^{-7/8} \, 
\|h\|^4_{L^2(M)}.
\end{equation}

Let $q=\tfrac{2(n+2)}n$ as in Lemma~\ref{leelemma} and note that $q<q_c$.  Also,
$$| \tilde \sigma_\lambda h \,  \tilde \sigma_\lambda h |^{q_c/2}
\le 2^{q/2} | \tilde \sigma_\lambda h \,  \tilde \sigma_\lambda h |^{\frac{q_c-q}2}
\cdot
\bigl(|\Upsilon^{\text{diag}}(h)|^{q/2}+|\Upsilon^{\text{far}}(h)|^{q/2}\bigr).
$$
As a result, taking $h=\rho_\lambda f$ and norms over $A_-$ as in \eqref{2.44},
\begin{multline}\label{5.8}
\|\tilde \sigma_\lambda h\|^{q_c}_{L^{q_c}(A_-)}=\int_{A_-}  | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h|^{q_c/2} \, dx
\\
\lesssim \int_{A_-} | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h|^{\frac{q_c-q}2} \, |\Upsilon^{\text{diag}}(h)|^{q/2} \, dx
\\
+ \int_{A_-} | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h|^{\frac{q_c-q}2} \, |\Upsilon^{\text{far}}(h)|^{q/2} \, dx  
= I + II.
\end{multline}

To estimate $II$ we use \eqref{5.7}, the ceiling for $A_-$ in \eqref{2.17} and the fact that, by \eqref{2.11}, $\tilde \sigma_\lambda =\tilde \rho_\lambda f$,
to conclude that
\begin{multline*}
II\lesssim \|\tilde \rho_\lambda f\|^{q_c-q}_{L^\infty(A_-)} \cdot \lambda^{1+\varepsilon} (\lambda^{7/8})^{\frac{n-1}2(q-q_c)} \|h\|^q_2
\\
\lesssim \lambda^{(\frac{n-1}4+\frac18)(q_c-q)} \, \lambda^{-(q_c-q)(\frac78 \cdot \frac{n-1}2)} \cdot \lambda^{1+\varepsilon}
=O(\lambda^{1-\delta_n+\varepsilon}).
\end{multline*}
Here $\delta_n>0$ since $(q_c-q)(\tfrac{3(n-1)}{16}-\tfrac18)>0$, and we also used the fact that
$\|h\|_2=\|\rho_\lambda f\|_2=O(1)$ by \eqref{2.15}.

Since we may take $\varepsilon<\delta_n$, $II^{1/q_c}$ is dominated by the last term in \eqref{2.44}.  Consequently, to finish the 
proof of this inequality, we just need to see that we also have suitable bounds for $I^{1/q_c}$.  To do so we use H\"older's inequality
followed by Young's inequality and \eqref{star} to see that
\begin{align*}
I&\le \|\tilde \sigma_\lambda h\cdot \tilde \sigma_\lambda h\|_{L^{q_c/2}(A_-)}^{\frac{q_c-q}2} \cdot C \| \Upsilon^{\text{diag}}(h)\|^{q/2}_{L^{q_c/2}}
\\
&\le \tfrac{q_c-q}{q_c} \|\tilde \sigma_\lambda h\cdot \tilde \sigma_\lambda h\|_{L^{q_c/2}(A_-)}^{q_c/2}
+\tfrac{q}{q_c} C \|\Upsilon^{\text{diag}}(h)\|_{L^{q_c/2}}^{q_c/2}
\\
&\le \tfrac{q_c-q}{q_c} \|\tilde \sigma_\lambda h \|^{q_c}_{L^{q_c}(A_-)} + C'
\sum_\nu \|\tilde \sigma_\lambda A^{\theta_0}_\nu h\|^{q_c}_{L^{q_c}}+O(\lambda^{1-}).
\end{align*}
Since $\tfrac{q_c-q}{q_c}<1$, the first term in the right can be absorbed in the left side
of \eqref{5.8}, and this along with the earlier estimate for $II$ yields \eqref{2.44}  when $n\ge3$.

If $n=2$, we shall still use \eqref{5.8}, and note that the estimate for the term $II$ also hold for $n=2$, so it suffices to modify the arguments for the first term $I$. Since , $q=\frac{2(n+2)}{n}=4$ and $q_c=6$ if $n=2$, by \eqref{organize}, we have 
\begin{equation}\label{5.8n2}
\begin{aligned}
    I&=
\int_{A_-} | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h| \, |\Upsilon^{\text{diag}}(h)|^{2} \, dx  \\
&\le \int_{A_-} | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h| \, |{\overline\Upsilon^{\text{diag}}}(h)| \, dx +\int_{A_-} | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h| \, |{\overline\Upsilon^{\text{far}}}(h)| \, dx \\
&= A+B 
\end{aligned}
\end{equation}

To estimate $B$ we use \eqref{5.7'}, the ceiling for $A_-$ in \eqref{2.17} and the fact that, by \eqref{2.11}, $\tilde \sigma_\lambda =\tilde \rho_\lambda f$,
to conclude that
\begin{equation*}
    B\lesssim \|\tilde \rho_\lambda f\|^{2}_{L^\infty(A_-)} \cdot \lambda^{1+\varepsilon} \lambda^{-7/8} \|h\|^4_2
\lesssim \lambda^{(\frac{1}4+\frac18)(2)} \, \lambda^{-\frac78} \cdot \lambda^{1+\varepsilon}
=O(\lambda^{1-\frac18+\varepsilon}).
\end{equation*}
Since we may take $\varepsilon<\frac18$, $B^{1/6}$ is dominated by the last term in \eqref{2.44}. Thus, we just need to see that we also have suitable bounds for $A^{1/6}$. By  H\"older's inequality,  Young's inequality and \eqref{star2}, we have
\begin{align*}
A
&\le \|\tilde\sigma_\lambda h \,  \tilde\sigma_\lambda h\|_{L^{3}(A_-)} \cdot \|{\overline\Upsilon^{\text{diag}}}(h)\|_{L^{3/2}(M)}
\\
&\le \tfrac{1}{3}  \|\tilde\sigma_\lambda h \,  \tilde\sigma_\lambda h\|_{L^{3}(A_-)}^{3} + \tfrac{2}{3} \|{\overline\Upsilon^{\text{diag}}}(h)\|_{L^{3/2}(M)}^{3/2}
\\
&\le \tfrac{1}{3}  \|\tilde\sigma_\lambda h \,  \tilde\sigma_\lambda h \|_{L^{3}(A_-)}^{3} +C
 \sum_{\nu}  \, \|\tilde\sigma_\lambda A^{\theta_0}_{\nu}  h\|_{L^{6}(M)}^{6}\, \, + \, \lambda^{1-}.
\end{align*}
The first term in the right can be absorbed in the left side
of \eqref{5.8}, and this along with the earlier estimates yields \eqref{2.44}  when $n=2$.

The proof of \eqref{2.45} is much simpler since we do not have to restrict to the set $A_{-}$. Since 
$$| \tilde \sigma_\lambda h \,  \tilde \sigma_\lambda h |^{q/2}
\le 2^{q/2} 
\cdot
\bigl(|\Upsilon^{\text{diag}}(h)|^{q/2}+|\Upsilon^{\text{far}}(h)|^{q/2}\bigr),
$$
we have 
\begin{equation}\label{5.8q}
\|\tilde \sigma_\lambda h\|^{q}_{L^{q}(M)}=\int  | \tilde \sigma_\lambda h \cdot \tilde \sigma_\lambda h|^{q/2} \, dx
\lesssim \int \, |\Upsilon^{\text{diag}}(h)|^{q/2} \, dx
+ \int |\Upsilon^{\text{far}}(h)|^{q/2} \, dx .
\end{equation}
Thus \eqref{2.45} simply follows from applying \eqref{star1} for the first term and \eqref{5.7q} for the second term on the right side.

